// Shared type definitions matching the architecture specification

// ============================================================
// Data Models
// ============================================================

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

// ============================================================
// Event Bus Contract
// ============================================================

export interface IEventBus {
  publish(event: string, payload: unknown): void;
  subscribe(event: string, callback: (payload: unknown) => void): void;
}

// Event payloads
export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

// ============================================================
// Service Contracts
// ============================================================

export interface IUserService {
  create(input: { name: string; email: string }): User;
  getById(id: string): User;
  getAll(): User[];
  update(id: string, input: Partial<{ name: string; email: string }>): User;
  delete(id: string): void;
}

export interface IProjectService {
  create(input: { name: string; description: string }): Project;
  getById(id: string): Project;
  getAll(): Project[];
  update(id: string, input: Partial<{ name: string; description: string }>): Project;
  delete(id: string): void;
  addMember(projectId: string, userId: string): Project;
  removeMember(projectId: string, userId: string): Project;
}

export interface ITaskService {
  create(input: { title: string; description: string; projectId: string }): Task;
  getById(id: string): Task;
  getByProject(projectId: string): Task[];
  update(id: string, input: Partial<{ title: string; description: string }>): Task;
  delete(id: string): void;
  assign(taskId: string, assigneeId: string): Task;
  changeStatus(taskId: string, newStatus: TaskStatus): Task;
}

export interface ICommentService {
  create(input: { taskId: string; authorId: string; body: string }): Comment;
  getById(id: string): Comment;
  getByTask(taskId: string): Comment[];
  delete(id: string): void;
}

export interface INotificationService {
  getByUser(userId: string): Notification[];
  markAsRead(notificationId: string): Notification;
}

// Optional lookup helpers to avoid cross-service imports while enriching events
export type GetUserName = (userId: string) => string | null;
export type GetTaskTitle = (taskId: string) => string | null;

import { IEventBus } from "./types";

export class EventBus implements IEventBus {
  private subscribers: Map<string, Array<(payload: unknown) => void>> = new Map();

  publish(event: string, payload: unknown): void {
    const subs = this.subscribers.get(event);
    if (subs) {
      for (const cb of subs) {
        try {
          cb(payload);
        } catch (err) {
          // Swallow subscriber errors to not break publisher flow
          // In real system, we'd log this
        }
      }
    }
  }

  subscribe(event: string, callback: (payload: unknown) => void): void {
    const subs = this.subscribers.get(event) ?? [];
    subs.push(callback);
    this.subscribers.set(event, subs);
  }
}

import { randomUUID } from "node:crypto";
import { IUserService, User } from "../types";

export class UserService implements IUserService {
  // Exclusive in-memory data store for users
  private users: Map<string, User> = new Map();

  create(input: { name: string; email: string }): User {
    const id = randomUUID();
    const user: User = { id, name: input.name, email: input.email };
    this.users.set(id, user);
    return user;
  }

  getById(id: string): User {
    const user = this.users.get(id);
    if (!user) throw new Error("User not found");
    return user;
  }

  getAll(): User[] {
    return Array.from(this.users.values());
  }

  update(id: string, input: Partial<{ name: string; email: string }>): User {
    const existing = this.users.get(id);
    if (!existing) throw new Error("User not found");
    const updated: User = {
      ...existing,
      ...input,
    };
    this.users.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.users.has(id)) throw new Error("User not found");
    this.users.delete(id);
  }

  // Helper for other layers (not other services): get user name by id
  public getUserName(id: string): string | null {
    const user = this.users.get(id);
    return user ? user.name : null;
  }
}

import { randomUUID } from "node:crypto";
import { IProjectService, Project } from "../types";

export class ProjectService implements IProjectService {
  // Exclusive in-memory store
  private projects: Map<string, Project> = new Map();

  create(input: { name: string; description: string }): Project {
    const id = randomUUID();
    const project: Project = { id, name: input.name, description: input.description, memberIds: [] };
    this.projects.set(id, project);
    return project;
  }

  getById(id: string): Project {
    const proj = this.projects.get(id);
    if (!proj) throw new Error("Project not found");
    return proj;
  }

  getAll(): Project[] {
    return Array.from(this.projects.values());
  }

  update(id: string, input: Partial<{ name: string; description: string }>): Project {
    const existing = this.projects.get(id);
    if (!existing) throw new Error("Project not found");
    const updated: Project = { ...existing, ...input } as Project;
    this.projects.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.projects.has(id)) throw new Error("Project not found");
    this.projects.delete(id);
  }

  addMember(projectId: string, userId: string): Project {
    const proj = this.getById(projectId);
    if (!proj.memberIds.includes(userId)) {
      proj.memberIds.push(userId);
      this.projects.set(projectId, proj);
    }
    return proj;
  }

  removeMember(projectId: string, userId: string): Project {
    const proj = this.getById(projectId);
    proj.memberIds = proj.memberIds.filter((id) => id !== userId);
    this.projects.set(projectId, proj);
    return proj;
  }
}

import { randomUUID } from "node:crypto";
import {
  CommentAddedPayload,
  IEventBus,
  ITaskService,
  Task,
  TaskAssignedPayload,
  TaskStatus,
  TaskStatusChangedPayload,
} from "../types";

export class TaskService implements ITaskService {
  // Exclusive in-memory store for tasks
  private tasks: Map<string, Task> = new Map();

  constructor(private bus: IEventBus) {}

  create(input: { title: string; description: string; projectId: string }): Task {
    const id = randomUUID();
    const task: Task = {
      id,
      title: input.title,
      description: input.description,
      status: "todo",
      assigneeId: null,
      projectId: input.projectId,
    };
    this.tasks.set(id, task);
    return task;
  }

  getById(id: string): Task {
    const t = this.tasks.get(id);
    if (!t) throw new Error("Task not found");
    return t;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter((t) => t.projectId === projectId);
  }

  update(id: string, input: Partial<{ title: string; description: string }>): Task {
    const existing = this.getById(id);
    const updated: Task = { ...existing, ...input } as Task;
    this.tasks.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.tasks.has(id)) throw new Error("Task not found");
    this.tasks.delete(id);
  }

  assign(taskId: string, assigneeId: string): Task {
    const task = this.getById(taskId);
    const updated: Task = { ...task, assigneeId };
    this.tasks.set(taskId, updated);
    const payload: TaskAssignedPayload = { taskId, taskTitle: updated.title, assigneeId };
    this.bus.publish("task.assigned", payload);
    return updated;
  }

  changeStatus(taskId: string, newStatus: TaskStatus): Task {
    const task = this.getById(taskId);
    const allowedOrder: TaskStatus[] = ["todo", "in-progress", "done"];
    const currentIndex = allowedOrder.indexOf(task.status);
    const newIndex = allowedOrder.indexOf(newStatus);
    if (newIndex === -1) throw new Error("Invalid status");
    // Enforce forward-only one-step transitions
    if (newIndex !== currentIndex + 1) {
      throw new Error("Invalid status transition: must progress todo → in-progress → done");
    }
    const updated: Task = { ...task, status: newStatus };
    this.tasks.set(taskId, updated);
    const payload: TaskStatusChangedPayload = {
      taskId,
      taskTitle: updated.title,
      assigneeId: updated.assigneeId,
      oldStatus: task.status,
      newStatus,
    };
    this.bus.publish("task.statusChanged", payload);
    return updated;
  }
}

import { randomUUID } from "node:crypto";
import {
  Comment,
  CommentAddedPayload,
  ICommentService,
  IEventBus,
} from "../types";

export class CommentService implements ICommentService {
  private comments: Map<string, Comment> = new Map();

  constructor(private bus: IEventBus) {}

  create(input: { taskId: string; authorId: string; body: string }): Comment {
    const id = randomUUID();
    const comment: Comment = {
      id,
      taskId: input.taskId,
      authorId: input.authorId,
      body: input.body,
      createdAt: new Date().toISOString(),
    };
    this.comments.set(id, comment);
    // Publish event with minimal data; enrichment is done by subscribers using their own lookups
    const payload: CommentAddedPayload = {
      commentId: id,
      taskId: input.taskId,
      taskTitle: "", // will be enriched by subscribers if needed
      authorId: input.authorId,
      authorName: "", // will be enriched by subscribers if needed
    };
    this.bus.publish("comment.added", payload);
    return comment;
  }

  getById(id: string): Comment {
    const c = this.comments.get(id);
    if (!c) throw new Error("Comment not found");
    return c;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter((c) => c.taskId === taskId);
  }

  delete(id: string): void {
    if (!this.comments.has(id)) throw new Error("Comment not found");
    this.comments.delete(id);
  }
}

import { randomUUID } from "node:crypto";
import {
  CommentAddedPayload,
  IEventBus,
  INotificationService,
  Notification,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
  GetTaskTitle,
  GetUserName,
} from "../types";

export class NotificationService implements INotificationService {
  private notifications: Map<string, Notification> = new Map();

  constructor(
    private bus: IEventBus,
    // Lookup helpers passed from main/router to avoid cross-service imports
    private getUserName: GetUserName,
    private getTaskTitle: GetTaskTitle,
    private getTaskAssigneeId: (taskId: string) => string | null,
  ) {}

  private createForUser(userId: string, message: string): Notification {
    const id = randomUUID();
    const notif: Notification = {
      id,
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.notifications.set(id, notif);
    return notif;
  }

  wireSubscriptions(): void {
    this.bus.subscribe("task.assigned", (payload) => {
      const p = payload as TaskAssignedPayload;
      const title = this.getTaskTitle(p.taskId) || p.taskTitle;
      this.createForUser(p.assigneeId, `Task '${title}' assigned to you`);
    });

    this.bus.subscribe("task.statusChanged", (payload) => {
      const p = payload as TaskStatusChangedPayload;
      const title = this.getTaskTitle(p.taskId) || p.taskTitle;
      if (p.assigneeId) {
        this.createForUser(p.assigneeId, `Task '${title}' status changed to ${p.newStatus}`);
      }
    });

    this.bus.subscribe("comment.added", (payload) => {
      const p = payload as CommentAddedPayload;
      const title = this.getTaskTitle(p.taskId) || p.taskTitle || "Task";
      const assigneeId = this.getTaskAssigneeId(p.taskId);
      if (assigneeId) {
        const authorName = this.getUserName(p.authorId) || p.authorName || "Someone";
        this.createForUser(assigneeId, `New comment on '${title}' by ${authorName}`);
      }
    });
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values()).filter((n) => n.userId === userId);
  }

  markAsRead(notificationId: string): Notification {
    const n = this.notifications.get(notificationId);
    if (!n) throw new Error("Notification not found");
    const updated: Notification = { ...n, read: true };
    this.notifications.set(notificationId, updated);
    return updated;
  }
}

import { createServer, IncomingMessage, ServerResponse } from "node:http";
import { parse as parseUrl } from "node:url";
import { IUserService, IProjectService, ITaskService, ICommentService, INotificationService, TaskStatus } from "./types";

export class Router {
  constructor(
    private userService: IUserService,
    private projectService: IProjectService,
    private taskService: ITaskService,
    private commentService: ICommentService,
    private notificationService: INotificationService,
  ) {}

  private async readBody(req: IncomingMessage): Promise<any> {
    return new Promise((resolve, reject) => {
      let data = "";
      req.on("data", (chunk) => (data += chunk));
      req.on("end", () => {
        if (!data) return resolve({});
        try {
          resolve(JSON.parse(data));
        } catch (e) {
          reject(new Error("Invalid JSON"));
        }
      });
      req.on("error", reject);
    });
  }

  private send(res: ServerResponse, status: number, body: unknown): void {
    const json = JSON.stringify(body);
    res.statusCode = status;
    res.setHeader("Content-Type", "application/json");
    res.setHeader("Content-Length", Buffer.byteLength(json));
    res.end(json);
  }

  private notFound(res: ServerResponse): void {
    this.send(res, 404, { error: "Not Found" });
  }

  private methodNotAllowed(res: ServerResponse): void {
    this.send(res, 405, { error: "Method Not Allowed" });
  }

  handler = async (req: IncomingMessage, res: ServerResponse) => {
    try {
      const parsed = parseUrl(req.url || "", true);
      const pathname = parsed.pathname || "/";
      const method = req.method || "GET";

      // Users
      if (pathname === "/users") {
        if (method === "GET") return this.send(res, 200, this.userService.getAll());
        if (method === "POST") {
          const body = await this.readBody(req);
          return this.send(res, 201, this.userService.create(body));
        }
        return this.methodNotAllowed(res);
      }

      const userMatch = pathname.match(/^\/users\/([^/]+)$/);
      if (userMatch) {
        const id = userMatch[1];
        if (method === "GET") return this.send(res, 200, this.userService.getById(id));
        if (method === "PUT") {
          const body = await this.readBody(req);
          return this.send(res, 200, this.userService.update(id, body));
        }
        if (method === "DELETE") {
          this.userService.delete(id);
          return this.send(res, 204, {});
        }
        return this.methodNotAllowed(res);
      }

      // Projects
      if (pathname === "/projects") {
        if (method === "GET") return this.send(res, 200, this.projectService.getAll());
        if (method === "POST") {
          const body = await this.readBody(req);
          return this.send(res, 201, this.projectService.create(body));
        }
        return this.methodNotAllowed(res);
      }

      const projectMatch = pathname.match(/^\/projects\/([^/]+)$/);
      if (projectMatch) {
        const id = projectMatch[1];
        if (method === "GET") return this.send(res, 200, this.projectService.getById(id));
        if (method === "PUT") {
          const body = await this.readBody(req);
          return this.send(res, 200, this.projectService.update(id, body));
        }
        if (method === "DELETE") {
          this.projectService.delete(id);
          return this.send(res, 204, {});
        }
        return this.methodNotAllowed(res);
      }

      const projectMembersMatch = pathname.match(/^\/projects\/([^/]+)\/members$/);
      if (projectMembersMatch) {
        const id = projectMembersMatch[1];
        if (method === "POST") {
          const body = await this.readBody(req);
          return this.send(res, 200, this.projectService.addMember(id, body.userId));
        }
        if (method === "DELETE") {
          const body = await this.readBody(req);
          return this.send(res, 200, this.projectService.removeMember(id, body.userId));
        }
        return this.methodNotAllowed(res);
      }

      // Tasks
      if (pathname === "/tasks") {
        if (method === "GET") {
          const projectId = (parsed.query["projectId"] as string) || "";
          return this.send(res, 200, this.taskService.getByProject(projectId));
        }
        if (method === "POST") {
          const body = await this.readBody(req);
          return this.send(res, 201, this.taskService.create(body));
        }
        return this.methodNotAllowed(res);
      }

      const taskMatch = pathname.match(/^\/tasks\/([^/]+)$/);
      if (taskMatch) {
        const id = taskMatch[1];
        if (method === "GET") return this.send(res, 200, this.taskService.getById(id));
        if (method === "PUT") {
          const body = await this.readBody(req);
          return this.send(res, 200, this.taskService.update(id, body));
        }
        if (method === "DELETE") {
          this.taskService.delete(id);
          return this.send(res, 204, {});
        }
        return this.methodNotAllowed(res);
      }

      const taskStatusMatch = pathname.match(/^\/tasks\/([^/]+)\/status$/);
      if (taskStatusMatch) {
        const id = taskStatusMatch[1];
        if (method === "PUT") {
          const body = await this.readBody(req);
          return this.send(res, 200, this.taskService.changeStatus(id, body.status as TaskStatus));
        }
        return this.methodNotAllowed(res);
      }

      const taskAssignMatch = pathname.match(/^\/tasks\/([^/]+)\/assign$/);
      if (taskAssignMatch) {
        const id = taskAssignMatch[1];
        if (method === "PUT") {
          const body = await this.readBody(req);
          return this.send(res, 200, this.taskService.assign(id, body.assigneeId));
        }
        return this.methodNotAllowed(res);
      }

      // Comments
      if (pathname === "/comments") {
        if (method === "GET") {
          const taskId = (parsed.query["taskId"] as string) || "";
          return this.send(res, 200, this.commentService.getByTask(taskId));
        }
        if (method === "POST") {
          const body = await this.readBody(req);
          return this.send(res, 201, this.commentService.create(body));
        }
        return this.methodNotAllowed(res);
      }

      const commentMatch = pathname.match(/^\/comments\/([^/]+)$/);
      if (commentMatch) {
        const id = commentMatch[1];
        if (method === "GET") return this.send(res, 200, this.commentService.getById(id));
        if (method === "DELETE") {
          this.commentService.delete(id);
          return this.send(res, 204, {});
        }
        return this.methodNotAllowed(res);
      }

      // Notifications
      if (pathname === "/notifications") {
        if (method === "GET") {
          const userId = (parsed.query["userId"] as string) || "";
          return this.send(res, 200, this.notificationService.getByUser(userId));
        }
        return this.methodNotAllowed(res);
      }

      const notifMatch = pathname.match(/^\/notifications\/([^/]+)\/read$/);
      if (notifMatch) {
        const id = notifMatch[1];
        if (method === "PUT") {
          return this.send(res, 200, this.notificationService.markAsRead(id));
        }
        return this.methodNotAllowed(res);
      }

      return this.notFound(res);
    } catch (err: any) {
      const message = err?.message || "Internal Server Error";
      this.send(res, 400, { error: message });
    }
  };
}

export function createHttpServer(router: Router) {
  return createServer(router.handler);
}

